<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';
require_once __DIR__.'/csrf_helper.php';
require_once __DIR__.'/includes/sports_activity.php';
require_once __DIR__.'/includes/ui_shell.php';
if(!isset($_SESSION['trener_id'])){header('Location: login.php');exit;}
$actor=(int)$_SESSION['trener_id'];$personId=(int)($_POST['person_id']??$_GET['person_id']??0);$error='';
try{sportsActivityAssertActor($pdo,$actor,$personId);}catch(RuntimeException $e){http_response_code(403);exit($e->getMessage());}
$from=(string)($_POST['from']??$_GET['from']??date('Y-01-01'));$to=(string)($_POST['to']??$_GET['to']??date('Y-m-d'));
try{sportsActivityDate($from);sportsActivityDate($to);if($from>$to)throw new InvalidArgumentException('Začátek období musí být před koncem.');}catch(InvalidArgumentException $e){http_response_code(422);exit($e->getMessage());}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??''))){http_response_code(403);exit('Formulář vypršel.');}
    try{
        if(($_POST['action']??'')==='statement')sportsActivityStatement($pdo,$personId,$from,$to,$actor,($_POST['confirmed']??'')==='1');
        elseif(($_POST['action']??'')==='participation')sportsEventRecord($pdo,(int)($_POST['event_id']??0),$personId,$actor,array_replace($_POST,['confirmed'=>($_POST['confirmed']??'')==='1']),(int)($_POST['expected_version']??0),(string)($_POST['request_key']??''));
        else throw new InvalidArgumentException('Neplatný úkon.');
        header('Location: sports_activity_admin.php?person_id='.$personId.'&from='.rawurlencode($from).'&to='.rawurlencode($to),true,303);exit;
    }catch(InvalidArgumentException|RuntimeException $e){http_response_code(422);$error=$e->getMessage();}
}
function sportsH(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$search=trim((string)($_GET['q']??''));$people=[];
if($search!==''&&mb_strlen($search)<=80){$q=$pdo->prepare("SELECT s.id,s.jmeno,s.prijmeni FROM sportovci s WHERE (s.jmeno LIKE ? OR s.prijmeni LIKE ? OR s.id=?) AND ".coachScopePersonPredicate($pdo).' ORDER BY s.prijmeni,s.jmeno LIMIT 25');$q->execute(['%'.$search.'%','%'.$search.'%',ctype_digit($search)?(int)$search:0]);$people=$q->fetchAll(PDO::FETCH_ASSOC);}
$summary=$personId>0?sportsActivitySummary($pdo,$personId,$from,$to):null;$current=$personId>0?sportsEventCurrent($pdo,$personId):[];
$statements=[];$history=[];if($personId>0){$q=$pdo->prepare('SELECT * FROM sports_activity_statements WHERE sportovec_id=? ORDER BY id DESC LIMIT 50');$q->execute([$personId]);$statements=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT r.*,p.event_id FROM sports_event_revisions r JOIN sports_event_participation p ON p.id=r.participation_id WHERE p.sportovec_id=? ORDER BY r.id DESC LIMIT 100');$q->execute([$personId]);$history=$q->fetchAll(PDO::FETCH_ASSOC);}
?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ověřená sportovní činnost</title><?php appUiAssets();?></head><body><?php require __DIR__.'/hlavicka.php';?><main class="container py-4"><h1>Ověřená sportovní činnost</h1><p>Počty vycházejí z uzavřené docházky a doložených startů. Podklad uchovává konkrétní verze; schválení odměn a výplaty řeší samostatná agenda.</p><p><a href="club_calendar.php">Kalendář klubových akcí</a></p>
<?php if($error):?><div class="alert alert-danger"><?=sportsH($error)?></div><?php endif;?>
<form method="get" class="mb-3"><label>Najít osobu <input name="q" value="<?=sportsH($search)?>" maxlength="80"></label><button>Hledat</button></form><?php foreach($people as $p):?><p><a href="?person_id=<?=(int)$p['id']?>"><?=sportsH($p['prijmeni'].' '.$p['jmeno'])?></a></p><?php endforeach;?>
<?php if($summary):?><h2 class="h4">Osoba #<?=$personId?></h2><form method="get"><input type="hidden" name="person_id" value="<?=$personId?>"><label>Od <input name="from" type="date" value="<?=sportsH($from)?>"></label> <label>Do <input name="to" type="date" value="<?=sportsH($to)?>"></label> <button>Zobrazit období</button></form><p class="lead"><?=(int)$summary['training_count']?> uzavřených tréninků · <?=(int)$summary['training_minutes']?> doložených minut · <?=(int)$summary['race_count']?> doložených startů</p><p>Neznámá délka: <?=(int)$summary['unknown_duration_count']?>. Historické záznamy bez ověření docházky se do těchto počtů nezapočítávají.</p><p><a href="sports_activity_export.php?person_id=<?=$personId?>&amp;from=<?=sportsH($from)?>&amp;to=<?=sportsH($to)?>">Export skutečné činnosti CSV</a></p>
<table class="table"><thead><tr><th>Datum</th><th>Činnost / zdroj</th><th>Verze</th><th>Minuty</th><th>Výsledek</th></tr></thead><tbody><?php foreach($summary['activities'] as $a):?><tr><td><?=sportsH($a['date'])?></td><td><?=sportsH(['training'=>'Trénink','race'=>'Závod','event'=>'Akce'][$a['kind']])?> #<?=(int)$a['activity_id']?></td><td><?=(int)$a['version']?> / revize #<?=(int)$a['revision_id']?></td><td><?=$a['duration_minutes']===null?'Neznámé':(int)$a['duration_minutes']?></td><td><?=sportsH(implode(' ',array_filter([$a['result_status'],$a['result_value'],$a['result_unit']],static fn($v)=>$v!==null)))?></td></tr><?php endforeach;?></tbody></table>
<h2 class="h4">Měření za období</h2><p>Původní hodnota a jednotka zůstávají zachovány. Neznámé jednotky a časy se nedopočítávají. Zátěžové testy a zdravotní podklady nejsou součástí tohoto exportu.</p><p><a href="sports_activity_export.php?person_id=<?=$personId?>&amp;from=<?=sportsH($from)?>&amp;to=<?=sportsH($to)?>&amp;kind=measurements">Export měření CSV</a> · <a href="medical_clearance_status.php?person_id=<?=$personId?>&amp;on=<?=date('Y-m-d')?>">Platnost zdravotního podkladu</a></p><table class="table"><tr><th>Datum / trénink / měření</th><th>Typ</th><th>Původní vzdálenost</th><th>Původní čas</th><th>Normalizované hodnoty</th></tr><?php foreach($summary['measurements'] as $m):?><tr><td><?=sportsH($m['activity_date'])?> / #<?=(int)$m['training_id']?> / #<?=(int)$m['id']?></td><td><?=sportsH($m['typ'])?></td><td><?=sportsH($m['vzdalenost']??'Neznámé')?> <?=sportsH($m['distance_unit']??'(jednotka neznámá)')?></td><td><?=sportsH($m['cas']??'Neznámé')?></td><td><?=sportsH($m['distance_meters']??'Neznámé')?> m · <?=sportsH($m['duration_ms']??'Neznámé')?> ms · RPE <?=sportsH($m['rpe_value']??'Neznámé')?></td></tr><?php endforeach;?></table><h2 class="h4">Účast na akci / oprava skutečnosti</h2><p>Nominace, potvrzení a registrace pořadateli neprokazují start. Oprava ukládá novou dohledatelnou verzi. Změnu přihlášky nebo finančního závazku vyřiďte v kalendáři a finanční agendě.</p>
<table class="table"><tr><th>Akce</th><th>Stav</th><th>Aktuální verze</th></tr><?php foreach($current as $r):$s=json_decode($r['snapshot_json'],true);?><tr><td>#<?=(int)$r['event_id']?> <?=sportsH($s['event_name'])?></td><td><?=sportsH(sportsActivityStages()[$r['stage']])?></td><td><?=(int)$r['version']?></td></tr><?php endforeach;?></table>
<form method="post" class="border rounded p-3 mb-4"><?=csrf_field()?><input type="hidden" name="action" value="participation"><input type="hidden" name="person_id" value="<?=$personId?>"><input type="hidden" name="from" value="<?=sportsH($from)?>"><input type="hidden" name="to" value="<?=sportsH($to)?>"><input type="hidden" name="request_key" value="<?=sportsH($_POST['request_key']??'sport:'.bin2hex(random_bytes(20)))?>">
<div class="row g-3"><div class="col-md-4"><label>Číslo akce z kalendáře<input class="form-control" type="number" name="event_id" min="1" required></label></div><div class="col-md-4"><label>Aktuální verze (nový záznam 0)<input class="form-control" type="number" name="expected_version" min="0" value="0" required></label></div><div class="col-md-4"><label>Stav účasti<select class="form-select" name="stage"><?php foreach(sportsActivityStages() as $key=>$label):?><option value="<?=$key?>"><?=sportsH($label)?></option><?php endforeach;?></select></label></div><div class="col-md-4"><label>Datum skutečné účasti<input type="date" class="form-control" name="actual_date" max="<?=date('Y-m-d')?>"></label></div><div class="col-md-4"><label>Stav výsledku<select name="result_status" class="form-select"><?php foreach([''=>'Bez výsledku','UNKNOWN'=>'Neznámý výsledek','FINISHED'=>'Dokončil','DNS'=>'Nestartoval','DNF'=>'Nedokončil','DSQ'=>'Diskvalifikován'] as $v=>$label):?><option value="<?=$v?>"><?=sportsH($label)?></option><?php endforeach;?></select></label></div><div class="col-md-4"><label>Původní hodnota výsledku<input class="form-control" name="result_value" maxlength="255"></label></div><div class="col-md-4"><label>Jednotka, je-li doložena<input class="form-control" name="result_unit" maxlength="40"></label></div><div class="col-md-8"><label>Podklad / umístění papírového originálu<input class="form-control" name="source_reference" minlength="5" maxlength="1000" required></label></div><div class="col-12"><label>Důvod zápisu nebo opravy<input class="form-control" name="reason" minlength="10" maxlength="1000" required></label></div><div class="col-12"><label><input type="checkbox" name="confirmed" value="1" required> Ověřil/a jsem uvedený stav podle podkladu</label></div><div class="col-12"><button class="btn btn-primary">Uložit verzi účasti</button></div></div></form>
<h2 class="h4">Předání podkladu za období</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="statement"><input type="hidden" name="person_id" value="<?=$personId?>"><input type="hidden" name="from" value="<?=sportsH($from)?>"><input type="hidden" name="to" value="<?=sportsH($to)?>"><label><input type="checkbox" name="confirmed" value="1" required> Potvrzuji předání současných verzí skutečné činnosti</label> <button>Uložit neměnný podklad</button></form>
<table class="table"><tr><th>Podklad</th><th>Období</th><th>Kontrola proti aktuální evidenci</th></tr><?php foreach($statements as $s):$changed=!hash_equals($s['snapshot_hash'],sportsActivityHash(sportsActivitySummary($pdo,$personId,$s['date_from'],$s['date_to'])));?><tr><td><a href="sports_activity_export.php?statement_id=<?=(int)$s['id']?>">#<?=(int)$s['id']?> CSV</a></td><td><?=sportsH($s['date_from'].' – '.$s['date_to'])?></td><td><?=$changed?'ZMĚNA K POSOUZENÍ — původní podklad zachován':'Shodné s aktuální evidencí'?></td></tr><?php endforeach;?></table>
<h2 class="h4">Historie verzí účasti</h2><table class="table"><tr><th>Akce / verze</th><th>Stav</th><th>Podklad</th><th>Důvod / zapsal / kdy</th></tr><?php foreach($history as $r):?><tr><td>#<?=(int)$r['event_id']?> / <?=(int)$r['version']?></td><td><?=sportsH(sportsActivityStages()[$r['stage']])?></td><td><?=sportsH($r['source_reference'])?></td><td><?=sportsH($r['reason'])?> / #<?=(int)$r['actor_trainer_id']?> / <?=sportsH($r['recorded_at'])?></td></tr><?php endforeach;?></table><?php endif;?></main></body></html>
